class AT(object):
    """
    Class for AT commands
    """
    def __init__(self, ssh_session, cli_utils_obj, rat, device_config_name, apn,
                 ipv4_or_v6):
        self.device_path = None
        self.rat = rat
        self.device_config_name = device_config_name
        self.ssh_session = ssh_session
        self.apn = apn
        self.ipv4_or_v6 = ipv4_or_v6
        self.cli_utils = cli_utils_obj
        self.serial_2tcp_session = Serial_Access(ssh_session)
        self.tty_path = None

    def attach_for_data(self):
        """
        Attached for data
        """
        # self.cli_utils.check_dongle_is_detected()
        self.ue_ip = self._run_attach_sequence_at_commands()
        time.sleep(10)
        logger.info("UE IP: {}".format(self.ue_ip))
        return self.ue_ip

    def detach(self):
        """
        Detach
        """
        self.run_detach_sequence_at_commands()
