    def start_voice_call(self):
        """
        Start voice call
        """
        with self.serial_2tcp_session.new_serial_2tcp_connection(self.tty_path, self.rat,
                                                                 self.device_config_name, 9041):
            self._run_AT_command('ATD123456;')
            self._run_AT_command('AT+CLCC')

    def stop_voice_call(self):
        """
        Stop voice call
        """
        with self.serial_2tcp_session.new_serial_2tcp_connection(self.tty_path, self.rat,
                                                                 self.device_config_name, 9051):
            self._run_AT_command('ATH')

    def start_quectel_daemon_get_ueip(self, max_attempts=4):
        attempt = 1
        while attempt <= max_attempts:
            try:
                logger.debug('\t' + '#' * 15 + ' Attach AT commands attempt: {} of {} '.format(attempt, max_attempts))
                self._attempt_starting_quectel_command()
                time.sleep(15)
                return self.cli_utils.get_ip_address()
            except (SerialConnectionException, ATCommandFailedException, PPPInterfaceNotFound,
                    ModemHungupError, PPPConnectScriptFailedError) as err:
                logger.debug("INFO: {}".format(err))
                attempt += 1
                self.cli_utils.stop_quectel_command()
                self.cli_utils.tty_path = self.tty_path = self.find_ttyUSBport_and_attach(
                    self.rat, self.device_config_name, attach_sequence='data')
            except Exception as err:
                attempt += 1
                logger.debug(err)
                self.cli_utils.stop_quectel_command()
                time.sleep(5)

