    def run_detach_sequence_at_commands(self):
        """
        Method to run at commands for Detach sequence
        """
        # self.device_path = self.cli_utils.check_dongle_is_detected(self.rat,
        # self.device_config_name)
        # Check if serial connection can be opened again or needs opened connection
        # Check if basic AT command is responding
        self._run_AT_command('at', max_attempts=3, timeout=5)
        self._run_AT_command('at+cfun?')
        self._run_AT_command('at+cfun=0')

    def _send_and_validate_attach_at_command(self, reattach):
        self._run_AT_command('at+cgatt?')
        # if reattach:
        #     self._run_AT_command('at+cgatt=0', max_attempts=2)
        self._run_AT_command('at+cgatt=1', max_attempts=2)
        attach_cmd_output = self._run_AT_command('at+cgatt?')
        self._verify_if_attach_succeeded(attach_cmd_output)

    def _verify_if_attach_succeeded(self, attach_cmd_output):
        attach_success_message = 'OK'
        if attach_success_message not in attach_cmd_output:
            raise DeviceNotAttachedException
        return True

    def _get_network_assigned_ipaddress(self):
        console_output = self._run_AT_command('at+cgpaddr=1')
        match_list = re.findall(r'\d+\.\d+\.\d+\.\d+', console_output)
        if len(match_list) > 0:
            return match_list[0]
        raise IPAddressNotAssigned

    def _get_ip_params(self):
        ue_ip, netmask, gw_ip = '', '', ''
        result = self._run_AT_command('at^dhcp?', max_attempts=3)
        if 'dhcp:' not in result.lower():
            logger.error('dhcp not found in result')
            raise
        lines = result.split('\n')
        for line in lines:
            if 'dhcp:' in line.lower():
                param_list = line.split(':')[1].split(',')
                ue_ip = self._convert_hex_to_ip(param_list[0])
                netmask = self._convert_hex_to_ip(param_list[1])
                gw_ip = self._convert_hex_to_ip(param_list[2])
                match_list = re.findall(r'\d+\.\d+\.\d+\.\d+', ue_ip)
                if len(match_list) == 0:
                    raise IPAddressNotAssigned('dhcp at command did not return IP')
                break
        return ue_ip, netmask, gw_ip

    def _run_AT_command(self, command, expected_output='OK', max_attempts=3, timeout=60):
        attempt = 1
        while attempt <= max_attempts:
            try:
                logger.debug('Individual AT command execution attempt {} of {}'.format(
                    attempt, max_attempts))
                console_output = self.serial_2tcp_session.write_command_and_return_output(
                    command, timeout=timeout)
                if expected_output in console_output:
                    time.sleep(3)
                    return console_output
                else:
                    attempt += 1
                    time.sleep(3)  # Sleep for sometime before next attempt
            except Exception as err:
                logger.debug('Exception while executing AT command. \n\t Error {}'.format(err))
                attempt += 1
                continue
        raise ATCommandFailedException

    def _convert_hex_to_ip(self, param):
        addr_long = int(param, 16)
        hex_ip = struct.pack("<L", addr_long)
        return socket.inet_ntoa(hex_ip)

    def find_ttyUSBport_and_attach(self, rat, device_config_name, attach_sequence='data'):
        """
        Method to find tty USBPorts, If IMEI of the device is match an attach sequence
        of Voice or Data based on parameter passed will be executed.
        """
        logger.debug('Finding ttyUSBport')
        ttyUSBdevices = self.cli_utils.get_all_ttyUSBdevices([])
        serial_port = 9010
        for index, USBdev in enumerate(ttyUSBdevices):
            logger.debug('\t' + '#' * 60 + '\n\t\tChecking USB device {} at position {}\n'.
                         format(USBdev, index))
            logger.debug('\t' + '#' * 60)
            try:
                with self.serial_2tcp_session.new_serial_2tcp_connection(USBdev, self.rat,
                                                                         self.device_config_name,
                                                                         serial_port):
                    try:
                        imei_matched = self._get_imei(USBdev, device_config_name, rat)
                        if imei_matched is not None:
                            if attach_sequence.lower() == 'data':
                                self._run_data_attach_commands()
                            elif attach_sequence.lower() == 'voice':
                                self._run_voice_attach_commands()
                            return USBdev
                    except ATCommandFailedException:
                        serial_port += 1
                        continue
            except Exception as err:
                logger.debug('Getting all USB list again')
                ttyUSBdevices = self.cli_utils.get_all_ttyUSBdevices(
                    ttyUSBdevices)
                logger.debug(err)
                logger.debug('Trying next USBdev')
                continue
        else:
            raise Exception('No USB device with matching IMEI was found')

    def _get_imei(self, USBdev, device_config_name, rat):
        # Check if basic AT command is responding
        self._run_AT_command('at', max_attempts=3, timeout=5)
        imei = get_config_variable(["ue_devices", rat, device_config_name, 'imei'])
        imei_matched = self._run_AT_command('at+gsn', max_attempts=3,
                                            expected_output=imei)
        logger.info('\t\t\t\t' + '*' * 80 + '\n\t\t\t\t\tGiven IMEI {}'
                                            ' matched with {} \n '.format(imei,
                                                                          USBdev))
        logger.info('\t\t\t\t' + '*' * 80)
        return imei_matched

    def find_ttyUSBport_and_detach(self, rat, device_config_name):
        """
        Method to find tty USBPorts, If IMEI of the device is matched, it
        returns the matched device name
        """
        logger.debug('Finding ttyUSBport')
        ttyUSBdevices = self.cli_utils.get_all_ttyUSBdevices([])
        serial_port = 9061
        for index, USBdev in enumerate(ttyUSBdevices):
            logger.debug('\t' + '#' * 60 + ' \n\t\tChecking USB device {} at position {}\n'
                         .format(USBdev, index))
            logger.debug('\t' + '#' * 60)
            try:
                with self.serial_2tcp_session.new_serial_2tcp_connection(USBdev, self.rat,
                                                                         self.device_config_name,
                                                                         serial_port):
                    try:
                        imei_matched = self._get_imei(USBdev, device_config_name, rat)
                        if imei_matched is not None:
                            logger.info('############ {}'.format(imei_matched))
                            self.detach()
                            return USBdev
                    except ATCommandFailedException:
                        serial_port += 1
                        continue
            except Exception as err:
                logger.debug('Getting all USB list again')
                ttyUSBdevices = self.cli_utils.get_all_ttyUSBdevices(ttyUSBdevices)
                logger.debug(err)
                logger.debug('Trying next USBdev')
                continue
        else:
            raise Exception('No USB device with matching IMEI was found')

    def _run_data_attach_commands(self):
        try:
            self._run_AT_command('at', max_attempts=3, timeout=10)
            self._run_AT_command('at+cfun?', timeout=10)
            self._run_AT_command('at+cfun=0', timeout=10)
            self._run_AT_command('at+cfun=1', timeout=10)
        except ATCommandFailedException:
            logger.debug("At command execution failed. Retrying...")
            raise ATCommandFailedException

    def _run_voice_attach_commands(self):
        try:
            # Check if basic AT command is responding
            self._run_AT_command('at', max_attempts=3, timeout=5)
            self._run_AT_command('at+cfun=0')
            # self._run_AT_command('AT+CGDCONT=1,"{}","{}"'.format(self.ipv4_or_v6, self.apn))
            self._run_AT_command('at+cfun=1')
            # self._run_AT_command('AT+QICSGP=1')
            self._run_AT_command('at+qnwinfo')
            self._run_AT_command('AT+QENG="servingcell"')
        except (ATCommandFailedException, DeviceNotDetectedException):
            logger.debug("At command execution failed. Retrying...")
            raise DeviceNotDetectedException

    def _reset_modem(self):
        logger.debug("Running reboot command on modem")
        port_number = 9071
        with self.serial_2tcp_session.new_serial_2tcp_connection(self.tty_path, self.rat,
                                                                 self.device_config_name,
                                                                 port_number):
            self._run_AT_command('at+cfun=1,1', max_attempts=3, timeout=10)
        time.sleep(60)

