    def _attempt_starting_quectel_command(self):
        try:
            self.cli_utils.start_quectel_command()
        except (PPPInterfaceNotFound, ModemHungupError, PPPConnectScriptFailedError) as e:
            logger.warn("Failed while attempting to start the quectel with error {} ".format(e))
            self._reset_modem()
            raise e
